head.script:
(function(){
  try{
    var stored = localStorage.getItem('ts-theme');
    var prefers = window.matchMedia('(prefers-color-scheme: dark)').matches;
    var theme = stored || (prefers ? 'dark' : 'light');
    document.documentElement.setAttribute('data-theme', theme);
  } catch(e){}
})();

head.b:skin:
:root{
  --bg:#fafaf7;
  --surface:#ffffff;
  --surface-alt:#f5f3ee;
  --text:#1a1a1a;
  --text-soft:#2c2c2c;
  --muted:#6b6b6b;
  --border:#e8e6e0;
  --border-strong:#d4d1c8;
  --accent:#b8161a;
  --accent-soft:#fef2f2;
  --accent-hover:#8c1014;
  --shadow:0 1px 3px rgba(0,0,0,.06);
  --shadow-md:0 4px 12px rgba(0,0,0,.08);
  --shadow-lg:0 16px 40px rgba(0,0,0,.12);
  --serif:'Playfair Display', Georgia, 'Times New Roman', serif;
  --body:'Lora', Georgia, 'Times New Roman', serif;
  --ui:'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --max:1100px;
  --max-narrow:780px;
}

html[data-theme='dark']{
  --bg:#0e0e10;
  --surface:#1a1a1d;
  --surface-alt:#222226;
  --text:#f0eee6;
  --text-soft:#dad7cc;
  --muted:#9a9a9a;
  --border:#2a2a2e;
  --border-strong:#3a3a40;
  --accent:#ef4444;
  --accent-soft:#2a1414;
  --accent-hover:#f87171;
  --shadow:0 1px 3px rgba(0,0,0,.4);
  --shadow-md:0 4px 12px rgba(0,0,0,.5);
  --shadow-lg:0 16px 40px rgba(0,0,0,.6);
}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{
  background:var(--bg);
  color:var(--text);
  font-family:var(--body);
  font-size:17px;
  line-height:1.7;
  -webkit-font-smoothing:antialiased;
  transition:background .2s, color .2s;
  min-height:100vh;
}
img{max-width:100%;height:auto;display:block}
a{color:var(--text);text-decoration:none;transition:color .15s}
a:hover{color:var(--accent)}

/* Reading progress bar */
.ts-progress{
  position:fixed;top:0;left:0;height:3px;width:0;
  background:var(--accent);z-index:9999;transition:width .1s linear;
}

/* Header */
.ts-header{
  border-bottom:1px solid var(--border);
  background:var(--bg);
  position:sticky;top:0;z-index:50;
  backdrop-filter:saturate(180%) blur(10px);
}
.ts-header-inner{
  max-width:var(--max);
  margin:0 auto;
  padding:18px 24px 14px;
  display:flex;flex-direction:column;align-items:center;gap:14px;
}
.ts-brand{
  font-family:var(--serif);
  font-weight:900;
  font-size:1.65rem;
  letter-spacing:-.5px;
  color:var(--text);
}
.ts-brand em{font-style:italic;color:var(--accent);font-weight:700}
.ts-tagline{
  font-family:var(--ui);
  font-size:.7rem;
  letter-spacing:2px;
  text-transform:uppercase;
  color:var(--muted);
  margin-top:-2px;
}
.ts-nav-wrap{
  display:flex;align-items:center;justify-content:center;
  gap:24px;width:100%;position:relative;
}
.ts-cat-nav{
  display:flex;flex-wrap:wrap;justify-content:center;
  gap:22px;font-family:var(--ui);font-size:.78rem;
  text-transform:uppercase;letter-spacing:1.8px;font-weight:600;
}
.ts-cat-nav a{
  color:var(--muted);padding:4px 0;
  border-bottom:2px solid transparent;
}
.ts-cat-nav a:hover,.ts-cat-nav a.active{color:var(--text);border-color:var(--accent)}
.ts-theme-toggle{
  position:absolute;right:0;
  background:none;border:1px solid var(--border-strong);
  color:var(--text);cursor:pointer;
  width:36px;height:36px;border-radius:50%;
  display:inline-flex;align-items:center;justify-content:center;
  font-size:14px;transition:.15s;
}
.ts-theme-toggle:hover{border-color:var(--accent);color:var(--accent)}
.ts-theme-toggle .ts-icon-sun{display:none}
.ts-theme-toggle .ts-icon-moon{display:inline}
html[data-theme='dark'] .ts-theme-toggle .ts-icon-sun{display:inline}
html[data-theme='dark'] .ts-theme-toggle .ts-icon-moon{display:none}

/* Container */
.ts-container{max-width:var(--max);margin:0 auto;padding:0 24px}

/* Eyebrow */
.ts-eyebrow{
  font-family:var(--ui);font-size:.72rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2.5px;color:var(--accent);
  margin-bottom:14px;
}

/* Featured story hero */
.ts-featured-mount{margin:48px 0 64px}
.ts-featured{
  display:grid;grid-template-columns:1fr;gap:0;
  background:var(--surface);border:1px solid var(--border);
  overflow:hidden;transition:transform .2s, box-shadow .2s;
}
.ts-featured:hover{box-shadow:var(--shadow-lg)}
.ts-featured-img{
  width:100%;aspect-ratio:16/9;object-fit:cover;
  background:var(--surface-alt);
}
.ts-featured-body{padding:40px 44px 44px}
.ts-featured-title{
  font-family:var(--serif);font-weight:900;
  font-size:clamp(1.8rem,3.4vw,2.8rem);
  line-height:1.15;letter-spacing:-.5px;margin-bottom:14px;
}
.ts-featured-title a{color:var(--text)}
.ts-featured-dek{
  font-family:var(--body);font-style:italic;font-size:1.1rem;
  color:var(--muted);margin-bottom:18px;line-height:1.55;
}
.ts-featured-meta{
  font-family:var(--ui);font-size:.78rem;
  text-transform:uppercase;letter-spacing:1.5px;color:var(--muted);
}
.ts-featured-meta strong{color:var(--text);font-weight:600}

/* Section labels */
.ts-section-label{
  display:flex;align-items:center;gap:16px;margin:64px 0 32px;
}
.ts-section-label h3{
  font-family:var(--ui);font-size:.78rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2.5px;color:var(--accent);
  white-space:nowrap;
}
.ts-section-label-line{flex:1;height:1px;background:var(--border)}

/* Index post grid */
.ts-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(280px,1fr));
  gap:40px 32px;margin:0 0 64px;
}
.ts-card{
  background:transparent;
  cursor:pointer;transition:transform .2s;
}
.ts-card:hover{transform:translateY(-3px)}
.ts-card-img{
  width:100%;aspect-ratio:16/10;object-fit:cover;
  background:var(--surface-alt);margin-bottom:18px;
  transition:filter .2s;
}
.ts-card:hover .ts-card-img{filter:brightness(.94)}
.ts-card-eyebrow{
  font-family:var(--ui);font-size:.68rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2px;color:var(--accent);
  margin-bottom:8px;
}
.ts-card-title{
  font-family:var(--serif);font-weight:700;
  font-size:1.32rem;line-height:1.25;letter-spacing:-.3px;
  margin-bottom:10px;
}
.ts-card-title a{color:var(--text)}
.ts-card-title a:hover{color:var(--accent)}
.ts-card-dek{
  font-family:var(--body);font-size:.98rem;color:var(--muted);
  line-height:1.55;margin-bottom:12px;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;
  overflow:hidden;
}
.ts-card-meta{
  font-family:var(--ui);font-size:.72rem;
  text-transform:uppercase;letter-spacing:1.2px;color:var(--muted);
}
.ts-card-meta span{margin-right:10px}

/* Pagination */
.ts-pagination{
  display:flex;justify-content:space-between;
  margin:48px 0 80px;padding-top:32px;border-top:1px solid var(--border);
  font-family:var(--ui);font-size:.85rem;
  text-transform:uppercase;letter-spacing:2px;font-weight:600;
}
.ts-pagination a{color:var(--text)}
.ts-pagination a:hover{color:var(--accent)}
.ts-pagination .spacer{flex:1}

/* Single post — article wrapper from publisher */
.ts-article{
  max-width:var(--max-narrow);
  margin:0 auto;padding:48px 24px 96px;
}
.ts-article-header{margin-bottom:40px;text-align:center}
.ts-article-header .ts-eyebrow{justify-content:center}
.ts-article-title{
  font-family:var(--serif);font-weight:900;
  font-size:clamp(2rem,4.8vw,3.2rem);
  line-height:1.1;letter-spacing:-.8px;
  color:var(--text);margin-bottom:18px;
}
.ts-article-dek{
  font-family:var(--body);font-style:italic;
  font-size:1.25rem;color:var(--muted);
  line-height:1.5;max-width:640px;margin:0 auto 22px;
}
.ts-article-byline{
  font-family:var(--ui);font-size:.78rem;
  color:var(--muted);text-transform:uppercase;letter-spacing:1.5px;
}
.ts-article-byline strong{color:var(--text);font-weight:600}

/* Hero figure */
.ts-hero-figure{margin:0 0 40px;position:relative}
.ts-hero-figure img{
  width:100%;aspect-ratio:16/9;object-fit:cover;
  background:var(--surface-alt);
}
.ts-hero-credit{
  position:absolute;bottom:8px;right:8px;
  font-family:var(--ui);font-size:.7rem;color:#fff;
  background:rgba(0,0,0,.6);padding:4px 10px;
  letter-spacing:.5px;
}

/* Article body typography */
.ts-article > p,
.ts-article > h2,
.ts-article > h3,
.ts-article > ul,
.ts-article > ol,
.ts-article > blockquote,
.ts-article > aside,
.ts-article > div,
.ts-article > section{
  margin-bottom:1.4em;
}

.ts-article > h2,
.ts-bottom-line > h2{
  font-family:var(--serif);font-weight:700;
  font-size:1.85rem;line-height:1.25;letter-spacing:-.4px;
  margin:2.2em 0 .7em;color:var(--text);scroll-margin-top:100px;
}
.ts-article > h3{
  font-family:var(--serif);font-weight:700;
  font-size:1.35rem;line-height:1.3;margin:1.8em 0 .5em;
}
.ts-article > p{
  font-family:var(--body);font-size:1.12rem;line-height:1.85;
  color:var(--text-soft);
}
.ts-article > p strong{color:var(--text);font-weight:600}
.ts-article > ul,.ts-article > ol{
  font-family:var(--body);font-size:1.08rem;line-height:1.8;
  color:var(--text-soft);padding-left:24px;
}
.ts-article > ul li,.ts-article > ol li{margin-bottom:.4em}

/* Drop cap on first paragraph after hero/header */
.ts-article > .ts-hero-figure + p::first-letter,
.ts-article > .ts-article-header + p::first-letter,
.ts-article > p:first-of-type::first-letter{
  font-family:var(--serif);font-weight:900;
  font-size:4.2em;line-height:.85;float:left;
  padding:6px 12px 0 0;color:var(--accent);
}

/* TL;DR box */
.ts-tldr{
  background:var(--accent-soft);
  border-left:3px solid var(--accent);
  padding:24px 28px;margin:32px 0;
}
.ts-tldr-label{
  font-family:var(--ui);font-size:.7rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2.5px;
  color:var(--accent);margin-bottom:12px;
}
.ts-tldr ul{list-style:none;padding:0;margin:0}
.ts-tldr li{
  font-family:var(--body);font-size:1.02rem;line-height:1.55;
  color:var(--text);padding:6px 0 6px 20px;position:relative;
}
.ts-tldr li::before{
  content:"";position:absolute;left:0;top:14px;
  width:8px;height:1px;background:var(--accent);
}

/* TOC */
.ts-toc{
  background:var(--surface-alt);border:1px solid var(--border);
  padding:22px 28px;margin:32px 0;
}
.ts-toc-title{
  font-family:var(--ui);font-size:.7rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2.5px;
  color:var(--muted);margin-bottom:12px;
}
.ts-toc ul{list-style:none;padding:0;margin:0}
.ts-toc li{
  font-family:var(--body);font-size:1rem;
  padding:5px 0;border-bottom:1px solid var(--border);
}
.ts-toc li:last-child{border-bottom:none}
.ts-toc a{
  color:var(--text-soft);font-weight:500;
  display:block;padding:2px 0;
}
.ts-toc a:hover{color:var(--accent)}

/* Pull quote */
.ts-pullquote{
  display:block;text-align:center;
  font-family:var(--serif);font-style:italic;font-weight:700;
  font-size:1.45rem;line-height:1.45;color:var(--text);
  border-top:1px solid var(--border-strong);
  border-bottom:1px solid var(--border-strong);
  padding:32px 16px;margin:40px 0;
}
.ts-pullquote-icon{
  display:block;font-style:normal;font-size:1.6rem;
  margin-bottom:14px;
}
.ts-pullquote-text strong{color:var(--accent);font-weight:700}

/* FAQ */
.ts-article > h2 + .ts-faq{margin-top:8px}
.ts-faq{margin:8px 0 32px}
.ts-faq-item{
  border-bottom:1px solid var(--border);padding:4px 0;
}
.ts-faq-item summary{
  font-family:var(--serif);font-weight:700;font-size:1.18rem;
  color:var(--text);padding:18px 32px 18px 0;
  cursor:pointer;list-style:none;position:relative;
  line-height:1.4;
}
.ts-faq-item summary::-webkit-details-marker{display:none}
.ts-faq-item summary::after{
  content:"+";position:absolute;right:4px;top:50%;
  transform:translateY(-50%);font-family:var(--ui);font-weight:300;
  font-size:1.4rem;color:var(--muted);transition:transform .2s;
}
.ts-faq-item[open] summary::after{content:"\2212"}
.ts-faq-item[open] summary{color:var(--accent)}
.ts-faq-answer{
  padding:0 0 22px;font-family:var(--body);
  font-size:1.05rem;line-height:1.75;color:var(--text-soft);
}
.ts-faq-answer p{margin-bottom:1em}

/* Bottom Line */
.ts-bottom-line{
  background:var(--surface-alt);
  padding:32px 36px;margin:48px 0 32px;
  border:1px solid var(--border);
}
.ts-bottom-line > h2{
  font-size:1.5rem;margin:0 0 .6em;color:var(--accent);
}
.ts-bottom-line > p{
  font-family:var(--body);font-size:1.1rem;line-height:1.7;
  color:var(--text);margin:0;
}

/* Share rail */
.ts-share-rail{
  display:flex;align-items:center;flex-wrap:wrap;gap:18px;
  padding:24px 0;border-top:1px solid var(--border);
  border-bottom:1px solid var(--border);margin:48px 0 32px;
  font-family:var(--ui);font-size:.82rem;
  text-transform:uppercase;letter-spacing:1.5px;
}
.ts-share-label{font-weight:700;color:var(--muted)}
.ts-share-link{
  color:var(--text-soft);font-weight:500;
  padding-bottom:2px;border-bottom:1px solid transparent;
}
.ts-share-link:hover{color:var(--accent);border-color:var(--accent)}

/* Related */
.ts-related-mount{margin:48px 0 24px}
.ts-related{margin-top:48px}
.ts-related-title{
  font-family:var(--ui);font-size:.78rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2.5px;color:var(--accent);
  margin-bottom:24px;text-align:center;
}
.ts-related-grid{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
  gap:28px;
}
.ts-related-card{display:block;color:var(--text)}
.ts-related-card-img{
  width:100%;aspect-ratio:16/10;object-fit:cover;
  background:var(--surface-alt);margin-bottom:12px;
}
.ts-related-card-title{
  font-family:var(--serif);font-weight:700;font-size:1.1rem;
  line-height:1.3;
}
.ts-related-card:hover .ts-related-card-title{color:var(--accent)}

/* Footer CTA */
.ts-footer-cta{
  margin:32px 0 0;padding:36px 32px;text-align:center;
  background:var(--surface-alt);border:1px solid var(--border);
}
.ts-footer-cta h4{
  font-family:var(--serif);font-weight:700;font-size:1.4rem;
  color:var(--text);margin-bottom:8px;
}
.ts-footer-cta p{
  font-family:var(--body);font-style:italic;color:var(--muted);
  margin-bottom:14px;
}
.ts-footer-cta-link{
  font-family:var(--ui);font-size:.85rem;font-weight:600;
  text-transform:uppercase;letter-spacing:1.5px;
  color:var(--accent);
  border-bottom:1px solid var(--accent);padding-bottom:2px;
}

/* Footer */
.ts-footer{
  border-top:1px solid var(--border);
  padding:48px 24px 32px;margin-top:80px;
  background:var(--surface-alt);
}
.ts-footer-inner{
  max-width:var(--max);margin:0 auto;
  display:grid;grid-template-columns:2fr 1fr 1fr;
  gap:48px;align-items:start;
}
.ts-footer-brand h5{
  font-family:var(--serif);font-weight:900;
  font-size:1.4rem;color:var(--text);margin-bottom:8px;
}
.ts-footer-brand h5 em{color:var(--accent);font-style:italic}
.ts-footer-brand p{
  font-family:var(--body);font-size:.95rem;
  color:var(--muted);line-height:1.6;
}
.ts-footer-col h6{
  font-family:var(--ui);font-size:.72rem;font-weight:700;
  text-transform:uppercase;letter-spacing:2px;
  color:var(--text);margin-bottom:14px;
}
.ts-footer-col ul{list-style:none}
.ts-footer-col li{margin-bottom:8px}
.ts-footer-col a{
  font-family:var(--ui);font-size:.9rem;color:var(--muted);
}
.ts-footer-col a:hover{color:var(--accent)}
.ts-footer-bottom{
  max-width:var(--max);margin:48px auto 0;padding-top:24px;
  border-top:1px solid var(--border);
  display:flex;justify-content:space-between;
  font-family:var(--ui);font-size:.78rem;color:var(--muted);
}
.ts-footer-disclaimer{
  max-width:var(--max);margin:18px auto 0;
  font-family:var(--ui);font-size:.74rem;color:var(--muted);
  line-height:1.6;font-style:italic;
}

/* Hide Blogger cruft */
.HTML1,.PageList1,#Attribution1,#Navbar1,.navbar{display:none !important}

/* Responsive */
@media (max-width:768px){
  body{font-size:16px}
  .ts-header-inner{padding:14px 20px 10px}
  .ts-brand{font-size:1.4rem}
  .ts-cat-nav{gap:14px;font-size:.7rem;letter-spacing:1.2px}
  .ts-theme-toggle{position:static;margin-left:auto}
  .ts-nav-wrap{flex-wrap:wrap}
  .ts-featured-body{padding:28px 24px 30px}
  .ts-featured-title{font-size:1.6rem}
  .ts-article{padding:32px 20px 64px}
  .ts-article-title{font-size:2rem}
  .ts-article-dek{font-size:1.05rem}
  .ts-article > h2,.ts-bottom-line > h2{font-size:1.55rem}
  .ts-article > p{font-size:1.06rem}
  .ts-footer-inner{grid-template-columns:1fr;gap:32px}
  .ts-footer-bottom{flex-direction:column;gap:8px;text-align:center}
  .ts-tldr,.ts-toc{padding:18px 22px}
  .ts-pullquote{font-size:1.2rem;padding:24px 12px}
  .ts-bottom-line{padding:24px 22px}
  .ts-faq-item summary{font-size:1.05rem}
}

@media (max-width:480px){
  .ts-grid{grid-template-columns:1fr;gap:32px}
  .ts-related-grid{grid-template-columns:1fr}
}

body.script:
//
(function(){
  // Theme toggle
  var btn = document.getElementById('ts-theme-btn');
  if (btn) {
    btn.addEventListener('click', function(){
      var cur = document.documentElement.getAttribute('data-theme') || 'light';
      var next = cur === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      try { localStorage.setItem('ts-theme', next); } catch(e){}
    });
  }

  // Reading progress bar
  var bar = document.getElementById('ts-progress-bar');
  if (bar) {
    window.addEventListener('scroll', function(){
      var h = document.documentElement;
      var s = h.scrollTop || document.body.scrollTop;
      var m = (h.scrollHeight || document.body.scrollHeight) - h.clientHeight;
      bar.style.width = (m > 0 ? (s / m * 100) : 0) + '%';
    }, { passive: true });
  }

  // Active nav highlight
  var path = location.pathname;
  document.querySelectorAll('.ts-cat-nav a').forEach(function(a){
    var href = a.getAttribute('href');
    if (href && href !== '/' && path.indexOf(href) !== -1) a.classList.add('active');
  });
  if (path === '/' || path === '' || /\/index\.html$/.test(path)) {
    var home = document.querySelector('.ts-nav-home');
    if (home) home.classList.add('active');
  }

  // Helper: extract first image from HTML string
  function firstImg(html){
    var m = /<img[^>]+src=["']([^"']+)["']/i.exec(html || '');
    return m ? m[1] : null;
  }
  function escapeHtml(s){
    return (s||'').replace(/[&<>"']/g, function(c){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }
  function truncate(s, n){
    s = (s||'').replace(/<[^>]+>/g,'').trim();
    return s.length > n ? s.slice(0, n).trim() + '…' : s;
  }

  // Featured story loader (homepage only)
  var featMount = document.getElementById('ts-featured-mount');
  if (featMount) {
    window.__tsFeatured = function(json){
      if (!json.feed || !json.feed.entry || !json.feed.entry.length) return;
      var e = json.feed.entry[0];
      var link = (e.link||[]).find(function(l){return l.rel === 'alternate';});
      if (!link) return;
      var img = firstImg(e.content && e.content.$t);
      var title = escapeHtml(e.title.$t);
      var dek = truncate(e.content && e.content.$t, 180);
      var date = new Date(e.published.$t);
      var dateStr = date.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});
      var cat = e.category && e.category.length ? escapeHtml(e.category[0].term) : 'Article';

      var imgHtml = img ? '<a href="'+link.href+'"><img class="ts-featured-img" src="'+img+'" alt="'+title+'"/></a>' : '';

      featMount.innerHTML =
        '<div class="ts-eyebrow" style="text-align:center;">Today&#8217;s Top Story</div>'+
        '<div class="ts-featured">'+
          imgHtml +
          '<div class="ts-featured-body">'+
            '<div class="ts-eyebrow">'+cat+'</div>'+
            '<h2 class="ts-featured-title"><a href="'+link.href+'">'+title+'</a></h2>'+
            '<p class="ts-featured-dek">'+escapeHtml(dek)+'</p>'+
            '<div class="ts-featured-meta">By <strong>TinkerStack</strong> &middot; '+dateStr+' &middot; 5 min read</div>'+
          '</div>'+
        '</div>';

      // Dedupe: remove the matching card from grid below
      var grid = document.getElementById('ts-card-grid');
      if (grid) {
        var cards = grid.querySelectorAll('.ts-card');
        cards.forEach(function(c){
          if (c.getAttribute('href') === link.href || c.dataset.url === link.href) {
            c.remove();
          }
        });
      }
    };
    var s = document.createElement('script');
    s.src = '/feeds/posts/default?alt=json-in-script&max-results=1&callback=__tsFeatured';
    document.body.appendChild(s);
  }

  // Related posts loader
  var relMount = document.querySelector('.ts-related-mount');
  if (relMount) {
    var labels = (relMount.dataset.labels || '').split(',').map(function(l){return l.trim();}).filter(Boolean);
    if (labels.length) {
      window.__tsRelated = function(json){
        if (!json.feed || !json.feed.entry) return;
        var here = location.pathname;
        var cards = json.feed.entry.filter(function(e){
          var u = (e.link||[]).find(function(l){return l.rel === 'alternate';});
          return u && u.href.indexOf(here) === -1;
        }).slice(0, 3);
        if (!cards.length) return;
        var html = '<div class="ts-related"><div class="ts-related-title">You Might Also Like</div><div class="ts-related-grid">';
        html += cards.map(function(e){
          var u = (e.link||[]).find(function(l){return l.rel === 'alternate';});
          var img = firstImg(e.content && e.content.$t);
          var imgEl = img ? '<img class="ts-related-card-img" src="'+img+'" alt=""/>' : '<div class="ts-related-card-img"></div>';
          return '<a class="ts-related-card" href="'+u.href+'">'+imgEl+'<div class="ts-related-card-title">'+escapeHtml(e.title.$t)+'</div></a>';
        }).join('');
        html += '</div></div>';
        relMount.innerHTML = html;
      };
      var r = document.createElement('script');
      r.src = '/feeds/posts/default/-/' + encodeURIComponent(labels[0]) + '?alt=json-in-script&max-results=6&callback=__tsRelated';
      document.body.appendChild(r);
    }
  }
})();
//
